import 'package:flutter/material.dart';
import '../core/app_state.dart';

class JourneyScreen extends StatefulWidget { final AppState state; const JourneyScreen({super.key, required this.state}); @override State<JourneyScreen> createState() => _JourneyScreenState(); }
class _JourneyScreenState extends State<JourneyScreen> { final destination = TextEditingController(); bool active = false; @override Widget build(BuildContext context) => Scaffold(appBar: AppBar(title: const Text('Journey mode')), body: ListView(padding: const EdgeInsets.all(20), children: [Text('Arrive safely', style: Theme.of(context).textTheme.headlineMedium?.copyWith(fontWeight: FontWeight.bold)), const SizedBox(height: 8), const Text('Share your route and let SafeHer check in if you stop unexpectedly.'), const SizedBox(height: 28), TextField(controller: destination, decoration: const InputDecoration(labelText: 'Where are you going?', prefixIcon: Icon(Icons.location_on_outlined))), const SizedBox(height: 16), SwitchListTile(value: true, onChanged: (_) {}, title: const Text('Share with trusted people'), subtitle: const Text('They’ll receive your ETA and arrival status')), const SizedBox(height: 20), FilledButton.icon(onPressed: () { if (destination.text.isNotEmpty) { widget.state.logEvent('Journey started', destination.text); setState(() => active = true); } }, icon: Icon(active ? Icons.check : Icons.route), label: Text(active ? 'Journey is active' : 'Start journey')), if (active) Card(margin: const EdgeInsets.only(top: 28), child: const ListTile(leading: Icon(Icons.shield, color: Colors.green), title: Text('You’re being looked after'), subtitle: Text('SafeHer will check in when you arrive.')))])); }
